/* ==========================================================================
 * 5. Internals
 *
 * The whole implementation is one translation unit, so every helper is
 * static. Only the vk* entry points have external linkage. Code must only
 * call vk* functions defined above it (so it builds under VK_NO_PROTOTYPES).
 * ========================================================================== */

#define PVK_API_VERSION VK_MAKE_API_VERSION(0, 1, 4, VK_HEADER_VERSION)
#define PVK_VENDOR_ID_APPLE 0x106B
#define PVK_MAX_QUEUES_PER_FAMILY 4
#define PVK_QUEUE_FAMILY_COUNT 2 /* section 7 */
#define PVK_MAX_QUEUES (PVK_MAX_QUEUES_PER_FAMILY * PVK_QUEUE_FAMILY_COUNT)
#define PVK_MEMORY_TYPE_COUNT 4 /* section 7 */
#define PVK_ARRAY_SIZE(a) (sizeof(a) / sizeof((a)[0]))

/* ---- Logging ----
 *
 * Every diagnostic is a message ("Debug messages", after section 6): it goes
 * to the VK_EXT_debug_utils messengers whose filters take it, and to stderr
 * when none did and PLASMAVK_LOG asks for its level, or always with the
 * debug layer (section 8, DEBUG LAYER). pvk_logi(NULL, ...) is a message no
 * instance owns: every instance's messengers see it. */

enum pvk_log_level { PVK_LOG_ERROR, PVK_LOG_WARN, PVK_LOG_INFO, PVK_LOG_DEBUG };

static int pvk_log_threshold = PVK_LOG_WARN;
static bool pvk_debug_env; /* PLASMAVK_DEBUG: the debug layer is on for every instance */
static pthread_once_t pvk_log_once = PTHREAD_ONCE_INIT;

/* Whether environment variable `name` is set, to something but "0". */
static bool pvk_env_on(const char *name)
{
    const char *value = getenv(name);
    return value && value[0] && strcmp(value, "0") != 0;
}

static void pvk_log_init(void)
{
    static const char *const names[] = { "error", "warn", "info", "debug" };
    const char *env = getenv("PLASMAVK_LOG");
    unsigned i;
    for (i = 0; env && i < PVK_ARRAY_SIZE(names); i++)
        if (strcmp(env, names[i]) == 0)
            pvk_log_threshold = (int)i;
    pvk_debug_env = pvk_env_on("PLASMAVK_DEBUG");
}

struct pvk_instance;
struct pvk_msg;
static VkBool32 pvk_vmessage(const struct pvk_msg *m, enum pvk_log_level level, const char *fmt, va_list args);

/* A message of instance (NULL: every instance) with id (pMessageIdName). */
static void pvk_logi(const struct pvk_instance *instance, enum pvk_log_level level, const char *id, const char *fmt, ...)
    __attribute__((format(printf, 4, 5)));

/* PLASMAVK_QUAD_MERGING (CONFIGURATION): fragment shaders don't keep their
 * 2x2 quads within a triangle (section 13, the fragment entry point). */
#ifdef PLASMAVK_QUAD_MERGING
#define PVK_QUAD_MERGING 1
#else
#define PVK_QUAD_MERGING 0
#endif

/* The version as "major.minor.patch". */
#define PVK_STR_(x) #x
#define PVK_STR(x) PVK_STR_(x)
#define PVK_VERSION_STRING                                                                                         \
    PVK_STR(PLASMAVK_VERSION_MAJOR) "." PVK_STR(PLASMAVK_VERSION_MINOR) "." PVK_STR(PLASMAVK_VERSION_PATCH)

/* ---- Allocation ---- */

/* Zeroed allocation through the application's callbacks, if any. */
static void *pvk_alloc(const VkAllocationCallbacks *alloc, size_t size, VkSystemAllocationScope scope)
{
    void *p;
    if (!alloc)
        return calloc(1, size);
    p = alloc->pfnAllocation(alloc->pUserData, size, 16, scope);
    if (p)
        memset(p, 0, size);
    return p;
}

static void pvk_free_raw(const VkAllocationCallbacks *alloc, void *p)
{
    if (!p)
        return;
    if (alloc)
        alloc->pfnFree(alloc->pUserData, p);
    else
        free(p);
}

/* Private data (section 9) is keyed by handle, and handles are the objects'
 * addresses: freeing an object drops its private data, so that an object
 * allocated later at the same address starts without any. */
static long pvk_private_data_entries; /* in all slots (atomic) */
static void pvk_private_data_forget(const void *object);
/* The same for VK_EXT_debug_utils object names and tags (section 9). */
static long pvk_named_objects; /* in all devices' tables (atomic) */
static void pvk_names_forget(const void *object);

/* Handles that have private data, and handles that have a name or tags,
 * counted in buckets by a hash of the handle: updated under the table's
 * lock, read without it (a count that reaches 255 stays). Freeing an object
 * whose bucket is 0 takes neither lock; the locks are global, so with one
 * object named anywhere, every free in every thread took them. */
#define PVK_MARK_BITS 13
static unsigned char pvk_private_data_marks[1u << PVK_MARK_BITS];
static unsigned char pvk_names_marks[1u << PVK_MARK_BITS];

static unsigned char *pvk_mark(unsigned char *marks, uint64_t handle)
{
    return &marks[(handle * 0x9e3779b97f4a7c15ull) >> (64 - PVK_MARK_BITS)];
}

/* An entry for handle was added (+1) or removed (-1). Table lock held. */
static void pvk_mark_add(unsigned char *marks, uint64_t handle, int delta)
{
    unsigned char *m = pvk_mark(marks, handle), n = __atomic_load_n(m, __ATOMIC_RELAXED);
    if (n != 255)
        __atomic_store_n(m, (unsigned char)(n + delta), __ATOMIC_RELAXED);
}

/* Whether handle may have an entry (entries: the table's count). The
 * bucket's load is relaxed: adding an object's entry happens before the
 * object is freed (the application synchronizes the two), so its count is
 * seen. */
static bool pvk_marked(unsigned char *marks, const long *entries, uint64_t handle)
{
    return __atomic_load_n(entries, __ATOMIC_ACQUIRE) && __atomic_load_n(pvk_mark(marks, handle), __ATOMIC_RELAXED);
}

/* What freeing an object drops, for an object whose memory is kept to be
 * the next of its kind (a descriptor set's). */
static void pvk_forget(const void *p)
{
    if (p && pvk_marked(pvk_private_data_marks, &pvk_private_data_entries, (uint64_t)(uintptr_t)p))
        pvk_private_data_forget(p);
    if (p && pvk_marked(pvk_names_marks, &pvk_named_objects, (uint64_t)(uintptr_t)p))
        pvk_names_forget(p);
}

static void pvk_free(const VkAllocationCallbacks *alloc, void *p)
{
    pvk_forget(p);
    pvk_free_raw(alloc, p);
}

/* ---- Helpers ---- */

static int pvk_find_extension(const VkExtensionProperties *list, uint32_t count, const char *name)
{
    uint32_t i;
    for (i = 0; i < count; i++)
        if (strcmp(list[i].extensionName, name) == 0)
            return (int)i;
    return -1;
}

/* 64-bit FNV-1a: a stable hash for identifiers that must be the same in
 * every process (section 7's UUIDs). Not for anything adversarial. */
static uint64_t pvk_hash64(uint64_t hash, const void *data, size_t size)
{
    const unsigned char *p = data;
    size_t i;
    for (i = 0; i < size; i++) {
        hash ^= p[i];
        hash *= 0x100000001b3ull;
    }
    return hash;
}

static uint64_t pvk_rotl64(uint64_t x, unsigned r)
{
    return (x << r) | (x >> (64 - r));
}

static uint64_t pvk_mix64(uint64_t x)
{
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdull;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ull;
    return x ^ (x >> 33);
}

/* A 128-bit hash of data and its size, continuing h (any seed): four
 * independent 64-bit multiply-rotate lanes over 32-byte blocks, then a
 * final mix. About 50 times as fast as pvk_hash64 on large inputs (SPIR-V,
 * MSL), for section 17's keys. Stable across processes (saved pipeline
 * caches hold keys); not for anything adversarial. */
static void pvk_hash128(uint64_t h[2], const void *data, size_t size)
{
    const unsigned char *p = data;
    uint64_t v[4], w[4], a, b;
    size_t i;
    unsigned l;
    v[0] = h[0] + 0x9e3779b97f4a7c15ull;
    v[1] = h[1] ^ 0xc2b2ae3d27d4eb4full;
    v[2] = h[0] ^ 0x165667b19e3779f9ull;
    v[3] = h[1] + 0x27d4eb2f165667c5ull;
    for (i = 0; i < size; i += 32) {
        if (size - i >= 32) {
            memcpy(w, p + i, 32);
        } else { /* the last bytes, zero-padded (the size tells them apart) */
            memset(w, 0, sizeof(w));
            memcpy(w, p + i, size - i);
        }
        for (l = 0; l < 4; l++)
            v[l] = pvk_rotl64(v[l] + w[l] * 0xc2b2ae3d27d4eb4full, 31) * 0x9e3779b97f4a7c15ull;
    }
    a = (pvk_rotl64(v[0], 1) + pvk_rotl64(v[1], 7) + pvk_rotl64(v[2], 12) + pvk_rotl64(v[3], 18)) ^ size;
    b = (v[0] ^ pvk_rotl64(v[1], 23)) + (v[2] ^ pvk_rotl64(v[3], 47)) + size * 0xff51afd7ed558ccdull;
    a += b;
    b += a;
    a = pvk_mix64(a);
    b = pvk_mix64(b);
    h[0] = a + b;
    h[1] = b + a + b;
}

/* The standard two-call enumeration (count query, then fill). */
static VkResult pvk_enumerate(const void *items, size_t item_size, uint32_t count,
                              uint32_t *pCount, void *pOut)
{
    uint32_t n;
    if (!pOut) {
        *pCount = count;
        return VK_SUCCESS;
    }
    n = *pCount < count ? *pCount : count;
    if (n)
        memcpy(pOut, items, n * item_size);
    *pCount = n;
    return n < count ? VK_INCOMPLETE : VK_SUCCESS;
}

/* ==========================================================================
 * 6. Extensions
 *
 * Advertised extensions: PlasmaVK's own (surfaces, swapchains, debug utils)
 * and, as Vulkan 1.4 drivers do, every extension promoted to Vulkan 1.1-1.4
 * whose functionality PlasmaVK has (Core Revisions). Applications written
 * for an older apiVersion enable those and call the core commands by their
 * KHR/EXT names (section 19). A promoted extension that needs a feature
 * Vulkan 1.4 leaves optional is offered only with that feature
 * (pvk_device_extension_features, section 7). An extension's own commands
 * get entries in section 19.
 * ========================================================================== */

enum pvk_instance_extension {
    PVK_INSTANCE_EXT_KHR_surface,
    PVK_INSTANCE_EXT_EXT_metal_surface,
    /* Surfaces without a window: presents show nothing (section 18) */
    PVK_INSTANCE_EXT_EXT_headless_surface,
    PVK_INSTANCE_EXT_KHR_portability_enumeration, /* accepted so MoltenVK-era apps keep working */
    /* No commands: the surface color spaces CAMetalLayer can show (section 18). */
    PVK_INSTANCE_EXT_EXT_swapchain_colorspace,
    /* Messengers, object names and labels (sections 8, 9, 15 and 16), also
     * provided by the debug layer below. Its device-level commands are
     * returned by vkGetDeviceProcAddr when the instance enabled it. */
    PVK_INSTANCE_EXT_EXT_debug_utils,
    /* Promoted to Vulkan 1.1: the physical device queries */
    PVK_INSTANCE_EXT_KHR_device_group_creation,
    PVK_INSTANCE_EXT_KHR_external_fence_capabilities,
    PVK_INSTANCE_EXT_KHR_external_memory_capabilities,
    PVK_INSTANCE_EXT_KHR_external_semaphore_capabilities,
    PVK_INSTANCE_EXT_KHR_get_physical_device_properties2,
    PVK_INSTANCE_EXTENSION_COUNT
};

